simulators = {
  "1": {
    "title": "Oersted Compass Deflection Lab",
    "description": "Replicate Hans Christian Oersted's historic 1820 experiment (Activity 12.1). Toggle electric current through a straight thick copper wire and observe compass needle deflection caused by the magnetic field.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Circuit Switch:</span>\n                        <button id=\"sim1_btn_switch\" onclick=\"sim1ToggleSwitch()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 text-slate-950 font-bold\">Current: ON (Closed)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current I (A):</span>\n                        <input type=\"range\" id=\"sim1_i_slider\" min=\"0.5\" max=\"5.0\" value=\"2.5\" step=\"0.5\" oninput=\"sim1Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim1_i_txt\" class=\"text-amber-400 font-mono font-bold\">2.5 A</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Wire Distance:</span>\n                        <input type=\"range\" id=\"sim1_d_slider\" min=\"15\" max=\"60\" value=\"25\" step=\"5\" oninput=\"sim1Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim1_d_txt\" class=\"text-teal-400 font-mono font-bold\">25 mm</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim1_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Compass Deflection (θ)</div>\n                        <div id=\"sim1_val_angle\" class=\"text-amber-400 font-bold text-sm\">38.5° East</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Magnetic Field at Needle</div>\n                        <div id=\"sim1_val_b\" class=\"text-teal-400 font-bold text-sm\">2.00 × 10⁻⁵ T</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Discovered By</div>\n                        <div id=\"sim1_val_scientist\" class=\"text-cyan-400 font-bold text-sm\">H. C. Oersted (1820)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Physical Deduction</div>\n                        <div id=\"sim1_val_deduction\" class=\"text-emerald-400 font-bold text-sm\">Current generates B-field</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "2": {
    "title": "Bar Magnet & Iron Filings Pattern",
    "description": "Simulate Activity 12.2. Sprinkle iron filings over cardboard surrounding a bar magnet and tap the sheet to observe induced magnetic dipoles organizing into continuous curved lines.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim2_btn_tap\" onclick=\"sim2TapBoard()\" class=\"px-3 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Tap Cardboard 👆</button>\n                        <button onclick=\"sim2ResetFilings()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Resprinkle Filings</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Magnet Pole Strength:</span>\n                        <input type=\"range\" id=\"sim2_str_slider\" min=\"1\" max=\"5\" value=\"3\" step=\"1\" oninput=\"sim2Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim2_str_txt\" class=\"text-amber-400 font-mono font-bold\">Medium (3×)</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim2_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Alignment Order</div>\n                        <div id=\"sim2_val_order\" class=\"text-amber-400 font-bold text-sm\">85% Aligned</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Line Density Peak</div>\n                        <div id=\"sim2_val_peak\" class=\"text-teal-400 font-bold text-sm\">Maximum at N & S Poles</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Filing Mechanism</div>\n                        <div id=\"sim2_val_mech\" class=\"text-cyan-400 font-bold text-sm\">Induced Dipole Alignment</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Field Representation</div>\n                        <div id=\"sim2_val_rep\" class=\"text-emerald-400 font-bold text-sm\">Continuous Lines of Force</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "3": {
    "title": "Compass Step-by-Step Field Line Tracer",
    "description": "Step through Activity 12.3 with a plotting compass. Advance step-by-step from the North pole to mark pencil dots and trace continuous closed loops ending at the South pole.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim3StepForward()\" class=\"px-3 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Step Compass Next →</button>\n                        <button onclick=\"sim3ResetTracing()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Reset Tracer</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Select Starting Trajectory:</span>\n                        <select id=\"sim3_line_select\" onchange=\"sim3ChangeLine()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"1\">Line 1 (Upper Tight Loop)</option>\n                            <option value=\"2\" selected>Line 2 (Central Wide Loop)</option>\n                            <option value=\"3\">Line 3 (Lower Tight Loop)</option>\n                        </select>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim3_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Tracer Progress</div>\n                        <div id=\"sim3_val_progress\" class=\"text-amber-400 font-bold text-sm\">Step 4 / 8</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">External Direction</div>\n                        <div id=\"sim3_val_ext\" class=\"text-teal-400 font-bold text-sm\">North → South</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Internal Direction</div>\n                        <div id=\"sim3_val_int\" class=\"text-cyan-400 font-bold text-sm\">South → North</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Loop Characteristic</div>\n                        <div id=\"sim3_val_loop\" class=\"text-emerald-400 font-bold text-sm\">Continuous Closed Curve</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "4": {
    "title": "Magnetic Field Vector & Non-Intersection Proof",
    "description": "Inspect field line properties in real time. Drag an inspection probe across space to examine local field tangent vectors and test why two lines cannot cross.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Probe Position X:</span>\n                        <input type=\"range\" id=\"sim4_px_slider\" min=\"50\" max=\"550\" value=\"280\" step=\"10\" oninput=\"sim4Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Probe Position Y:</span>\n                        <input type=\"range\" id=\"sim4_py_slider\" min=\"30\" max=\"230\" value=\"65\" step=\"10\" oninput=\"sim4Update()\" class=\"w-24 accent-amber-500\">\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim4_btn_intersect\" onclick=\"sim4TestIntersection()\" class=\"px-2.5 py-1 rounded-lg bg-rose-600 text-white font-bold\">Simulate Intersection Paradox</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim4_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Field Magnitude (Crowding)</div>\n                        <div id=\"sim4_val_mag\" class=\"text-amber-400 font-bold text-sm\">Moderate (0.35 T)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Tangent Direction Angle</div>\n                        <div id=\"sim4_val_angle\" class=\"text-teal-400 font-bold text-sm\">142° (Unique Vector)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Non-Intersection Law</div>\n                        <div id=\"sim4_val_intersect\" class=\"text-cyan-400 font-bold text-sm\">Strictly Separate Lines</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Physical Reason</div>\n                        <div id=\"sim4_val_reason\" class=\"text-emerald-400 font-bold text-sm\">Needle cannot point twice</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "5": {
    "title": "Current Reversal & Polarity Deflection Lab",
    "subtitle": "Activity 12.4 Current Direction vs Magnetic Orientation",
    "description": "Simulate Activity 12.4. Flip battery polarity to reverse electric current between North-to-South and South-to-North, observing how compass needle deflection reverses between East and West.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current Direction:</span>\n                        <button id=\"sim5_btn_n_s\" onclick=\"sim5SetDirection('N_S')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">North → South</button>\n                        <button id=\"sim5_btn_s_n\" onclick=\"sim5SetDirection('S_N')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">South → North</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Circuit State:</span>\n                        <button id=\"sim5_btn_key\" onclick=\"sim5ToggleKey()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 text-slate-950 font-bold\">Key Closed</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim5_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Current Flow Direction</div>\n                        <div id=\"sim5_val_flow\" class=\"text-amber-400 font-bold text-sm\">North to South</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">North Pole Deflection</div>\n                        <div id=\"sim5_val_deflect\" class=\"text-teal-400 font-bold text-sm\">Deflects toward EAST</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Governing Rule</div>\n                        <div id=\"sim5_val_rule\" class=\"text-cyan-400 font-bold text-sm\">SNOW / Right-Hand Rule</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Polarity Relationship</div>\n                        <div id=\"sim5_val_rel\" class=\"text-emerald-400 font-bold text-sm\">Field flips with Current</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "6": {
    "title": "Straight Wire Concentric Rings Field",
    "description": "Experiment with Activity 12.5. Adjust current magnitude I and compass radial distance r from a vertical wire to verify the fundamental law $B \\propto I / r$ with concentric circle patterns.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current I (A):</span>\n                        <input type=\"range\" id=\"sim6_i_slider\" min=\"1\" max=\"10\" value=\"4\" step=\"1\" oninput=\"sim6Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim6_i_txt\" class=\"text-amber-400 font-mono font-bold\">4.0 A</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Radial Distance r (cm):</span>\n                        <input type=\"range\" id=\"sim6_r_slider\" min=\"1\" max=\"8\" value=\"3\" step=\"0.5\" oninput=\"sim6Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim6_r_txt\" class=\"text-teal-400 font-mono font-bold\">3.0 cm</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim6_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Field Strength B</div>\n                        <div id=\"sim6_val_b\" class=\"text-amber-400 font-bold text-sm\">2.67 × 10⁻⁵ T</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Current Proportionality</div>\n                        <div id=\"sim6_val_iprop\" class=\"text-teal-400 font-bold text-sm\">B ∝ I (Direct)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Distance Proportionality</div>\n                        <div id=\"sim6_val_rprop\" class=\"text-cyan-400 font-bold text-sm\">B ∝ 1/r (Inverse)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Line Geometry</div>\n                        <div id=\"sim6_val_geom\" class=\"text-emerald-400 font-bold text-sm\">Concentric Circles</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "7": {
    "title": "Right-Hand Thumb Rule 3D Visualizer",
    "description": "Visualize the Right-Hand Thumb Rule and Maxwell's corkscrew rule. Test NCERT Example 12.1 for an East-to-West power line to view circulating field lines from East and West observer perspectives.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current Flow:</span>\n                        <select id=\"sim7_dir_select\" onchange=\"sim7Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"E_W\" selected>Example 12.1: East → West</option>\n                            <option value=\"W_E\">West → East</option>\n                            <option value=\"UP\">Vertical UP (Out of page)</option>\n                            <option value=\"DOWN\">Vertical DOWN (Into page)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Observer Perspective:</span>\n                        <button id=\"sim7_btn_east\" onclick=\"sim7SetView('east')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">View from East</button>\n                        <button id=\"sim7_btn_west\" onclick=\"sim7SetView('west')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">View from West</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim7_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Apparent Circulation</div>\n                        <div id=\"sim7_val_circ\" class=\"text-amber-400 font-bold text-sm\">Clockwise</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Field Directly Below Wire</div>\n                        <div id=\"sim7_val_below\" class=\"text-teal-400 font-bold text-sm\">Points toward NORTH</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Field Directly Above Wire</div>\n                        <div id=\"sim7_val_above\" class=\"text-cyan-400 font-bold text-sm\">Points toward SOUTH</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Equivalent Analogy</div>\n                        <div id=\"sim7_val_analogy\" class=\"text-emerald-400 font-bold text-sm\">Maxwell's Corkscrew</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "8": {
    "title": "Circular Loop Magnetic Field",
    "description": "Inspect Figures 12.8 & 12.9. Observe how concentric circular field lines around loop segments expand radially with distance and straighten into parallel lines at the center.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Loop Current Sense:</span>\n                        <button id=\"sim8_btn_cw\" onclick=\"sim8SetSense('cw')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Clockwise (South Face)</button>\n                        <button id=\"sim8_btn_ccw\" onclick=\"sim8SetSense('ccw')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Counter-Clockwise (North Face)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current I:</span>\n                        <input type=\"range\" id=\"sim8_i_slider\" min=\"1\" max=\"6\" value=\"3\" step=\"1\" oninput=\"sim8Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim8_i_txt\" class=\"text-amber-400 font-mono font-bold\">3 A</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim8_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Center Field Geometry</div>\n                        <div id=\"sim8_val_center\" class=\"text-amber-400 font-bold text-sm\">Straight & Parallel</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Center Field Direction</div>\n                        <div id=\"sim8_val_dir\" class=\"text-teal-400 font-bold text-sm\">Into the Screen</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Magnetic Polarity of Face</div>\n                        <div id=\"sim8_val_pole\" class=\"text-cyan-400 font-bold text-sm\">South Pole (Clock rule)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">All Segments Contribution</div>\n                        <div id=\"sim8_val_contrib\" class=\"text-emerald-400 font-bold text-sm\">Constructive Superposition</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "9": {
    "title": "Multi-Turn Coil Superposition Analyzer",
    "description": "Examine Activity 12.6. Adjust the number of tight turns n from 1 to 20 to verify that the magnetic field produced by a circular coil scales linearly as $B_{net} = n \\cdot B_1$ due to constructive vector addition.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Number of Turns (n):</span>\n                        <input type=\"range\" id=\"sim9_n_slider\" min=\"1\" max=\"20\" value=\"5\" step=\"1\" oninput=\"sim9Update()\" class=\"w-28 accent-amber-500\">\n                        <span id=\"sim9_n_txt\" class=\"text-amber-400 font-mono font-bold\">5 Turns</span>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current I (A):</span>\n                        <input type=\"range\" id=\"sim9_i_slider\" min=\"0.5\" max=\"4.0\" value=\"2.0\" step=\"0.5\" oninput=\"sim9Update()\" class=\"w-20 accent-amber-500\">\n                        <span id=\"sim9_i_txt\" class=\"text-teal-400 font-mono font-bold\">2.0 A</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim9_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Central Field B</div>\n                        <div id=\"sim9_val_btot\" class=\"text-amber-400 font-bold text-sm\">6.28 × 10⁻⁵ T</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Single Turn Field B₁</div>\n                        <div id=\"sim9_val_b1\" class=\"text-teal-400 font-bold text-sm\">1.26 × 10⁻⁵ T</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Turn Multiplier Factor</div>\n                        <div id=\"sim9_val_mult\" class=\"text-cyan-400 font-bold text-sm\">5× Amplification</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Current In Each Turn</div>\n                        <div id=\"sim9_val_sense\" class=\"text-emerald-400 font-bold text-sm\">Identical Circulation</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "10": {
    "title": "Solenoid Uniform Field Studio",
    "description": "Interact with Figure 12.10. Observe how the magnetic field of a cylindrical helical solenoid mimics a permanent bar magnet outside, while maintaining perfectly straight, parallel, uniform field lines inside.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current Sense:</span>\n                        <button id=\"sim10_btn_toggle\" onclick=\"sim10ToggleCurrent()\" class=\"px-3 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Left: North / Right: South</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Turn Density (N/L):</span>\n                        <input type=\"range\" id=\"sim10_density_slider\" min=\"6\" max=\"18\" value=\"12\" step=\"2\" oninput=\"sim10Update()\" class=\"w-24 accent-amber-500\">\n                        <span id=\"sim10_density_txt\" class=\"text-amber-400 font-mono font-bold\">12 Turns</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim10_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Internal Core Field</div>\n                        <div id=\"sim10_val_internal\" class=\"text-amber-400 font-bold text-sm\">Completely Uniform (Straight)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Internal Line Direction</div>\n                        <div id=\"sim10_val_intdir\" class=\"text-teal-400 font-bold text-sm\">South → North (Right to Left)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">External Field Analogy</div>\n                        <div id=\"sim10_val_analogy\" class=\"text-cyan-400 font-bold text-sm\">Permanent Bar Magnet</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Solenoid Formula</div>\n                        <div id=\"sim10_val_formula\" class=\"text-emerald-400 font-bold text-sm\">B = μ₀ · n · I</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "11": {
    "title": "Electromagnet Soft Iron Core Inducer",
    "description": "Simulate Figure 12.11. Insert a soft iron rod into the solenoid to align ferromagnetic domains and amplify magnetic strength, demonstrating instant demagnetization upon opening the switch.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Core Material:</span>\n                        <select id=\"sim11_core_select\" onchange=\"sim11Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"soft_iron\" selected>Soft Iron Core (High μ, Zero Retentivity)</option>\n                            <option value=\"air\">Air Core (Hollow Solenoid)</option>\n                            <option value=\"steel\">Hard Carbon Steel (Permanent Retentivity)</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim11_btn_power\" onclick=\"sim11TogglePower()\" class=\"px-3 py-1 rounded-lg bg-emerald-600 text-slate-950 font-bold\">Power: ENERGIZED</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim11_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Magnetic Amplification</div>\n                        <div id=\"sim11_val_amp\" class=\"text-amber-400 font-bold text-sm\">800× Core Boost</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Residual Magnetism</div>\n                        <div id=\"sim11_val_resid\" class=\"text-teal-400 font-bold text-sm\">Zero (Instant Demagnetize)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Lifting Capacity</div>\n                        <div id=\"sim11_val_lift\" class=\"text-cyan-400 font-bold text-sm\">45 Steel Pins Held</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Typical Applications</div>\n                        <div id=\"sim11_val_app\" class=\"text-emerald-400 font-bold text-sm\">Cranes, Relays & Bells</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "12": {
    "title": "Kicking Aluminium Rod Experiment",
    "description": "Replicate Activity 12.7. Suspend a conducting aluminium rod between horseshoe magnet poles. Toggle current and magnetic field polarities to observe mechanical kick deflections.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Current in Rod:</span>\n                        <button id=\"sim12_btn_curr\" onclick=\"sim12ToggleCurrent()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">B → A (Forward)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Magnet Poles:</span>\n                        <button id=\"sim12_btn_mag\" onclick=\"sim12ToggleMagnet()\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Bottom N / Top S (Upward B)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Angle θ:</span>\n                        <input type=\"range\" id=\"sim12_theta_slider\" min=\"0\" max=\"90\" value=\"90\" step=\"15\" oninput=\"sim12Update()\" class=\"w-16 accent-amber-500\">\n                        <span id=\"sim12_theta_txt\" class=\"text-teal-400 font-mono font-bold\">90°</span>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim12_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Mechanical Force Direction</div>\n                        <div id=\"sim12_val_force\" class=\"text-amber-400 font-bold text-sm\">Displaces to the LEFT</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Force Scaling (sin θ)</div>\n                        <div id=\"sim12_val_scaling\" class=\"text-teal-400 font-bold text-sm\">100% Maximum at 90°</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Governing Principle</div>\n                        <div id=\"sim12_val_principle\" class=\"text-cyan-400 font-bold text-sm\">Ampere's Reciprocal Force</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Parallel Angle (0°) Force</div>\n                        <div id=\"sim12_val_zero\" class=\"text-emerald-400 font-bold text-sm\">Exactly Zero Force</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "13": {
    "title": "Fleming's Left-Hand Rule Workbench",
    "description": "Master Figure 12.13 and solve Example 12.2. Align mutually perpendicular vectors: Forefinger (Field), Middle Finger (Current), and Thumb (Motion/Force) to predict charged particle deflections.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Scenario:</span>\n                        <select id=\"sim13_scenario_select\" onchange=\"sim13Update()\" class=\"bg-slate-800 text-slate-200 px-2 py-1 rounded border border-slate-700\">\n                            <option value=\"ex12_2\" selected>Example 12.2: Electron Beam (Velocity Right, Field Down)</option>\n                            <option value=\"proton\">Exercise Q2: Proton Beam (Velocity East, Deflected North)</option>\n                            <option value=\"motor\">Electric Motor Arm: Coil Current Forward, Field Right</option>\n                        </select>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button onclick=\"sim13FireParticle()\" class=\"px-3 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Fire Particle Beam 🚀</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim13_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Forefinger (Magnetic Field)</div>\n                        <div id=\"sim13_val_b\" class=\"text-amber-400 font-bold text-sm\">Vertically Downward (↓)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Middle Finger (Current)</div>\n                        <div id=\"sim13_val_i\" class=\"text-teal-400 font-bold text-sm\">Horizontally Left (←)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Thumb (Resulting Force)</div>\n                        <div id=\"sim13_val_f\" class=\"text-cyan-400 font-bold text-sm\">Into the Page (⊗)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Physical Devices</div>\n                        <div id=\"sim13_val_device\" class=\"text-emerald-400 font-bold text-sm\">Electric Motors & Loudspeakers</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "14": {
    "title": "Biomagnetism & Diagnostic MRI Studio",
    "description": "Explore the medical science behind Section 12.3. Observe how microscopic ionic currents along heart and brain neurons generate biomagnetic fields ($10^{-9}$ Earth field) for MRI diagnostics.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Target Organ:</span>\n                        <button id=\"sim14_btn_brain\" onclick=\"sim14SetOrgan('brain')\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 text-slate-950 font-bold\">Human Brain (Neural)</button>\n                        <button id=\"sim14_btn_heart\" onclick=\"sim14SetOrgan('heart')\" class=\"px-2.5 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Human Heart (Cardiac)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <button id=\"sim14_btn_rf\" onclick=\"sim14PulseRF()\" class=\"px-2.5 py-1 rounded-lg bg-indigo-600 hover:bg-indigo-500 text-white font-bold\">Apply RF Pulse (MRI Scan)</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim14_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Biomagnetic Field Magnitude</div>\n                        <div id=\"sim14_val_mag\" class=\"text-amber-400 font-bold text-sm\">~10⁻¹³ T (10⁻⁹ of Earth)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Biochemical Source</div>\n                        <div id=\"sim14_val_source\" class=\"text-teal-400 font-bold text-sm\">Na⁺ / K⁺ / Ca²⁺ Ionic Nerve Drift</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Target Nuclei in MRI</div>\n                        <div id=\"sim14_val_nuclei\" class=\"text-cyan-400 font-bold text-sm\">Water Hydrogen Protons</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Radiation Safety</div>\n                        <div id=\"sim14_val_safety\" class=\"text-emerald-400 font-bold text-sm\">Zero Ionizing Radiation</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "15": {
    "title": "Domestic 220V AC Electrical Installation",
    "description": "Inspect Figure 12.15. Trace Red Live (220V), Black Neutral (0V), and Green Earth wires supplying parallel 15A high-power and 5A lighting circuits with independent branch switches.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Toggle Appliances:</span>\n                        <button id=\"sim15_btn_lamp\" onclick=\"sim15ToggleLoad('lamp')\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">5A Lamp: ON</button>\n                        <button id=\"sim15_btn_fan\" onclick=\"sim15ToggleLoad('fan')\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">5A Fan: ON</button>\n                        <button id=\"sim15_btn_geyser\" onclick=\"sim15ToggleLoad('geyser')\" class=\"px-2 py-0.5 rounded bg-emerald-700 text-white text-[11px] font-bold\">15A Geyser: ON</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Main Switch:</span>\n                        <button id=\"sim15_btn_main\" onclick=\"sim15ToggleMain()\" class=\"px-2.5 py-1 rounded-lg bg-emerald-600 text-slate-950 font-bold\">Main: CLOSED</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim15_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Supply Voltage across Loads</div>\n                        <div id=\"sim15_val_voltage\" class=\"text-amber-400 font-bold text-sm\">Uniform 220 V AC (50 Hz)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Total Current Drawn</div>\n                        <div id=\"sim15_val_current\" class=\"text-teal-400 font-bold text-sm\">10.45 A (Normal Load)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Wire Color Code</div>\n                        <div id=\"sim15_val_color\" class=\"text-cyan-400 font-bold text-sm\">Red Live / Black Neutral / Green Earth</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Wiring Topology</div>\n                        <div id=\"sim15_val_top\" class=\"text-emerald-400 font-bold text-sm\">Independent Parallel Branches</div>\n                    </div>\n                </div>\n            </div>\n        "
  },
  "16": {
    "title": "Earth Wire & Fuse Safety Meltdown Lab",
    "description": "Simulate domestic faults. Contrast shock prevention via the earth wire against hazardous live chassis exposure, and trigger a short-circuit current surge to watch the fuse melt.",
    "html": "\n            <div class=\"space-y-4\">\n                <div class=\"flex flex-wrap items-center justify-between gap-2 p-2.5 rounded-xl bg-slate-900/80 border border-slate-800 text-xs\">\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Earth Wire Connection:</span>\n                        <button id=\"sim16_btn_earth\" onclick=\"sim16ToggleEarth()\" class=\"px-2.5 py-1 rounded-lg bg-emerald-600 text-white font-bold\">Earth Connected (Safe)</button>\n                    </div>\n                    <div class=\"flex items-center gap-2\">\n                        <span class=\"text-slate-400\">Simulate Fault:</span>\n                        <button id=\"sim16_btn_leak\" onclick=\"sim16SimulateInsulationLeak()\" class=\"px-2.5 py-1 rounded-lg bg-amber-600 hover:bg-amber-500 text-slate-950 font-bold\">Casing Leakage</button>\n                        <button id=\"sim16_btn_short\" onclick=\"sim16TriggerShortCircuit()\" class=\"px-2.5 py-1 rounded-lg bg-rose-600 hover:bg-rose-500 text-white font-bold\">Short-Circuit</button>\n                        <button onclick=\"sim16ResetSystem()\" class=\"px-2 py-1 rounded-lg bg-slate-800 hover:bg-slate-700 text-slate-300 font-medium\">Reset</button>\n                    </div>\n                </div>\n\n                <div class=\"relative w-full h-64 bg-slate-950 rounded-xl border border-slate-800 overflow-hidden flex items-center justify-center\">\n                    <canvas id=\"sim16_canvas\" width=\"600\" height=\"260\" class=\"w-full h-full\"></canvas>\n                </div>\n\n                <div class=\"grid grid-cols-2 sm:grid-cols-4 gap-2 text-center text-xs\">\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Appliance Chassis Potential</div>\n                        <div id=\"sim16_val_chassis\" class=\"text-emerald-400 font-bold text-sm\">0 V (Discharged into Earth)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Safety Fuse State</div>\n                        <div id=\"sim16_val_fuse\" class=\"text-amber-400 font-bold text-sm\">Conducting Intact</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">User Shock Status</div>\n                        <div id=\"sim16_val_shock\" class=\"text-cyan-400 font-bold text-sm\">Zero Shock Risk (Safe)</div>\n                    </div>\n                    <div class=\"p-2 rounded-lg bg-slate-900/60 border border-slate-800\">\n                        <div class=\"text-slate-400 text-[10px]\">Protection Mechanism</div>\n                        <div id=\"sim16_val_prot\" class=\"text-emerald-400 font-bold text-sm\">Low-R Earth Path + Joule Fuse</div>\n                    </div>\n                </div>\n            </div>\n        "
  }
}
